use vstd::prelude::*;

verus! {
    // ones_like produces a Vec<i32> of the same length as `a`,
    // with every entry equal to 1.
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        ensures
            // result has the same length as the input
            result.len() == a.len(),
        ensures
            // every element of result is 1
            forall |j: usize| j < a.len() ==> result[j] == 1,
    {
        let mut result: Vec<i32> = Vec::with_capacity(a.len());
        let mut i: usize = 0;
        let n = a.len();

        while i < n
            invariant
                // loop index never exceeds n
                i <= n,
            invariant
                // length of result so far equals i
                result.len() == i,
            invariant
                // all pushed elements are 1
                forall |j: usize| j < i ==> result[j] == 1,
            decreases
                // ensure termination
                n - i,
        {
            result.push(1);
            i += 1;
        }

        result
    }
}

